  'aurora': {"poster":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Aurora_Film_Corporation_Private_Limited_Entrance_-_Lenin_Sarani_-_Kolkata_2012-09-29_1412.JPG/500px-Aurora_Film_Corporation_Private_Limited_Entrance_-_Lenin_Sarani_-_Kolkata_2012-09-29_1412.JPG","synopsis":"Aurora Film Corporation is a film production company based in Kolkata, West Bengal, India, and primarily involved in producing Bengali films. Aurora has produced and distributed several landmark Bengali-language films including Satyajit Ray's Pather Panchali.","wikiUrl":"https://en.wikipedia.org/wiki/Aurora_Film_Corporation","qid":"Q16949440"},
