  'le-temps-retrouve': {"poster":"https://upload.wikimedia.org/wikipedia/en/b/b9/Temps_retrouve.jpg","cast":["Catherine Deneuve","Emmanuelle Béart","Vincent Perez","John Malkovich","Pascal Greggory","Marcello Mazzarella","Marie-France Pisier","Chiara Mastroianni"],"directors":["Raoul Ruiz"],"synopsis":"Le Temps retrouvé est un  film franco-italo-portugais réalisé par Raoul Ruiz d'après le roman homonyme de Marcel Proust et sorti en 1999.","wikiUrl":"https://fr.wikipedia.org/wiki/Le_Temps_retrouv%C3%A9_(film)","qid":"Q509605"},
