  'malina': {"poster":"https://upload.wikimedia.org/wikipedia/en/a/aa/Malina_1991_film_poster.jpg","cast":["Isabelle Huppert","Mathieu Carrière","Libgart Schwarz","Lisa Kreuzer","Lolita Chammah","Peter Kern","Can Togay","Isolde Barth"],"directors":["Werner Schroeter"],"synopsis":"Malina est un film germano-autrichien réalisé par Werner Schroeter en 1991, en compétition au Festival de Cannes 1991.","wikiUrl":"https://fr.wikipedia.org/wiki/Malina_(film%2C_1991)","qid":"Q3282107"},
  'palermo-oder-wolfsburg': {"poster":"https://upload.wikimedia.org/wikipedia/en/a/ac/Palermo_or_Wolfsburg.jpg","cast":["Ida Di Benedetto","Magdalena Montezuma","Otto Sander","Antonio Orlando","Gisela Hahn","Harry Baer","Ula Stöckl"],"directors":["Werner Schroeter"],"synopsis":"Palermo (Palermo oder Wolfsburg) est un film ouest-allemand réalisé par Werner Schroeter et sorti en 1980.","wikiUrl":"https://fr.wikipedia.org/wiki/Palermo_(film)","qid":"Q322107"},
  'neuf-vies-pour-un-chat': {"cast":["Liane Hielscher","Kristine de Loup","Heidi Stroh","Jürgen Arndt"],"directors":["Ula Stöckl"],"synopsis":"The Cat Has Nine Lives (German: Neun Leben hat die Katze) is a 1968 West German drama film written and directed by Ula Stöckl. It was screened in the Berlinale Classics section of the 65th Berlin International Film Festival.","wikiUrl":"https://en.wikipedia.org/wiki/The_Cat_Has_Nine_Lives","qid":"Q19571197"},
  'eclairage-intime': {"poster":"https://upload.wikimedia.org/wikipedia/en/6/6b/Intimate_Lighting_poster.jpg","cast":["Věra Křesadlová","Jan Vostrčil","Vlastimila Vlková","Jiří Růžička père","Karel Blažek","Zdeněk Bezušek","Jaroslava Štědrá","Karel Uhlík"],"directors":["Ivan Passer"],"synopsis":"Éclairage intime (Intimní osvětlení) est un film dramatique tchèque réalisé par Ivan Passer et sorti en 1965. Le film est le premier long-métrage du réalisateur et montre deux jours de la vie quotidienne d'une famille ordinaire dans un village.\nLe film a été tourné dans des intérieurs naturels par des acteurs non professionnels, ce qui apporte à l'œuvre un grand degré d'authenticité.","wikiUrl":"https://fr.wikipedia.org/wiki/%C3%89clairage_intime","qid":"Q3566402"},
