  'videodrome': {"poster":"https://upload.wikimedia.org/wikipedia/en/0/0f/Videodromeposter.jpg","cast":["James Woods","Sonja Smits","Debbie Harry","Leslie Carlson","Peter Dvorský","Jack Creley","Jayne Eastwood"],"directors":["David Cronenberg"],"synopsis":"Vidéodrome (Videodrome) est un film canadien réalisé par David Cronenberg et sorti en 1983.","wikiUrl":"https://fr.wikipedia.org/wiki/Vid%C3%A9odrome","qid":"Q747551"},
